export function pinView(file, src) {
  // nur auf den neuen Stand anwenden (Kontextzeilen reiner Löschungen kommen auch im alten Text vor)
  if (file === 'src/pages/Shifts.jsx' && src.includes('findSameStartShift(')) for (const [n, o] of SHIFTS_2B) src = src.replace(n, () => o)
  if (file === 'src/lib/supabase.js') { if (src.includes('deviceSignOutOptions(')) for (const [n, o] of SUPABASE_SIGNOUT_2A) src = src.replace(n, () => o); if (src.includes('withRequestTimeout(')) for (const [n, o] of SUPABASE_TIMEOUT_F3) src = src.replace(n, () => o); return src }
  if (file === 'src/pages/ClockIn.jsx') { if (src.includes('deriveClockStatus(')) for (const [n, o] of CLOCK_STATUS_F2) src = src.replace(n, () => o); return src }
  if (file === 'src/App.jsx') { if (src.includes('createRequestGate')) for (const [n, o] of APP_2C) src = src.replace(n, () => o); if (src.includes('profileLoadOutcome(')) for (const [n, o] of APP_PROFILE_LOAD) src = src.replace(n, () => o); return src }
  if (file === 'src/pages/Dashboard.jsx') { if (src.includes('nextLoadState(')) for (const [n, o] of DASH_2D) src = src.replace(n, () => o); if (src.includes('<AttentionPanel ')) for (const [n, o] of DASH_ATTENTION) src = src.replace(n, () => o); return src }   // Funktion: kein „$“-Muster im Ersatztext
  if (file === 'src/pages/TimeManagement.jsx') src = src.replace(TM_OVERLAP_IMPORT, '').replace(TM_OVERLAP_NEW, TM_OVERLAP_OLD)
  if (file === 'src/components/UI/TimeInput24.jsx') return src.replace(TIME_FOCUS, '').replace(TIME_VISUAL_FN, '').replace(TIME_VISUAL_NEW, TIME_VISUAL_OLD)
    .replace('maxLength={6} placeholder="HH:MM"', 'maxLength={5} placeholder="HH:MM"')
  if (file === 'src/lib/time24.js') return src.replace(TIME_PARSE_NEW, TIME_PARSE_OLD)
  if (!A11Y_ONLY.has(file)) return src
  if (file === 'src/pages/PayrollDocuments.jsx') src = payrollDocsFrozen(src)
  let s = src.replace(/ aria-label=\{(?:[^{}]|\{[^{}]*\})*\}/g, '').replace(/ aria-label="[^"]*"/g, '').replace(/ autoComplete="off"/g, '')
  if (file === 'src/pages/Shifts.jsx') s = s.replace(SWAP_NEW, SWAP_OLD).replace(SWAP_STATE, '').replace(/ disabled=\{swapBusyId === sw\.id\}/g, '')
  return s
}
